// Project Warehouse Audit — the view models behind Dashboard -> Audit.
//
// THE THREE ARRAYS BELOW ARE LOADED FROM POSTGRES AT RUNTIME
// (public.audit_ratings / audit_findings / audit_counts). They ship empty because this
// repository is public; the master copy is /private-data/auditReport.js (untracked),
// generated by scripts/import-audit-report.mjs from the workbook behind the Power BI
// report. src/lib/hydrate.js fills them IN PLACE and then calls rebuildAudit() — see
// CLAUDE.md for why in place matters (reassigning one silently breaks hydration).
//
// WHAT THIS MODULE IS FOR
// Everything here is a pure function of a row set. The tab narrows the three arrays
// once with selectAudit(filter) and hands the results to the shapers below, which is
// what lets one filter bar drive nine visuals without any of them re-deriving the
// filter. Nothing is cached across renders: the whole dataset is ~4,200 rows and the
// heaviest pass is a single group-by.
//
// EVERY FIGURE HERE WAS RECONCILED AGAINST THE .pbix'S OWN RENDERED NUMBERS, under no
// filter and under each of the three Project Type splits, before any of it was drawn.
// The one exception is documented on highRiskAreas() below — the report's own measure
// for that visual does not reconcile with its own source, so this one deviates
// deliberately. Everything else matches to the last percentage point.
import { CRITERIA_ORDER } from './auditCriteria'

export const AUDIT_RATINGS = []
export const AUDIT_FINDINGS = []
export const AUDIT_COUNTS = []

// ---------------------------------------------------------------------------
// Rebuilt vocabularies. All filled in place by rebuildAudit().
// ---------------------------------------------------------------------------

/** Project names, alphabetical — the Project filter's options. */
export const AUDIT_PROJECTS = []
/** Audit months present, 'YYYY-MM' ascending — the period filter's options. */
export const AUDIT_MONTHS = []
/** Years present, descending (newest first is how people pick a year). */
export const AUDIT_YEARS = []
/** The five inspection criteria, in the audit form's own numbered order. */
export const AUDIT_CRITERIA = []

// date|project -> 'Vertical' | 'Horizontal'. Absent where the source gives no type.
//
// Project Type is recorded ONLY on the findings rows, yet it filters the scorecard too —
// the Power BI model resolves that through a relationship on date + project. So it is
// treated here as a property of the AUDIT, rebuilt from the findings and applied to all
// three tables. This is exactly equivalent to reading the column row by row: across all
// 592 findings there is not one row whose own type disagrees with its audit's, and not
// one blank-typed row inside a typed audit. 11 of the 70 audits carry no type at all in
// the source; they stay untyped rather than being guessed at or dropped, and the filter
// offers them as "Unclassified".
const TYPE_BY_AUDIT = new Map()

/** The label used for an audit the source never classified. */
export const UNCLASSIFIED = 'Unclassified'

export const auditKey = (row) => `${row.date}|${row.project}`
export const typeOfAudit = (row) => TYPE_BY_AUDIT.get(auditKey(row)) || UNCLASSIFIED

const fill = (target, rows) => { target.length = 0; target.push(...rows) }

export function rebuildAudit() {
  TYPE_BY_AUDIT.clear()
  for (const f of AUDIT_FINDINGS) if (f.type) TYPE_BY_AUDIT.set(auditKey(f), f.type)

  const projects = new Set()
  const months = new Set()
  for (const r of AUDIT_RATINGS) { projects.add(r.project); months.add(r.date.slice(0, 7)) }
  // A project that only ever appears on a findings row (never scored) would be missing
  // from the filter and its findings unreachable, so both tables feed the list.
  for (const f of AUDIT_FINDINGS) projects.add(f.project)

  fill(AUDIT_PROJECTS, [...projects].filter(Boolean).sort())
  fill(AUDIT_MONTHS, [...months].filter(Boolean).sort())
  fill(AUDIT_YEARS, [...new Set(AUDIT_MONTHS.map((m) => m.slice(0, 4)))].sort().reverse())

  // The criteria list is taken from the data, then ordered by the audit form's own
  // numbering (criteria_num) rather than alphabetically, so the scorecard reads down
  // the page in the same order as the paper form.
  const seen = new Map()
  for (const r of AUDIT_RATINGS) if (!seen.has(r.criteria)) seen.set(r.criteria, r.num)
  for (const f of AUDIT_FINDINGS) if (f.criteria && !seen.has(f.criteria)) seen.set(f.criteria, CRITERIA_ORDER[f.criteria] ?? 99)
  fill(AUDIT_CRITERIA, [...seen.keys()].sort((a, b) => (seen.get(a) ?? 99) - (seen.get(b) ?? 99)))
}

// ---------------------------------------------------------------------------
// Filtering
// ---------------------------------------------------------------------------

/**
 * Narrow all three tables at once.
 * @param {{projects?: string[], types?: string[], from?: string, to?: string}} f
 *        projects/types empty or absent = no filter on that axis.
 *        from/to are inclusive 'YYYY-MM-DD' bounds.
 */
export function selectAudit(f = {}) {
  const projects = f.projects?.length ? new Set(f.projects) : null
  const types = f.types?.length ? new Set(f.types) : null
  const { from, to } = f

  const keep = (row) => {
    if (projects && !projects.has(row.project)) return false
    if (types && !types.has(typeOfAudit(row))) return false
    if (from && row.date < from) return false
    if (to && row.date > to) return false
    return true
  }

  return {
    ratings: AUDIT_RATINGS.filter(keep),
    findings: AUDIT_FINDINGS.filter(keep),
    counts: AUDIT_COUNTS.filter(keep),
  }
}

// ---------------------------------------------------------------------------
// Shared shaping helpers
// ---------------------------------------------------------------------------

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
export const monthLabel = (ym) => MONTHS[Number(String(ym).slice(5, 7)) - 1] || ''
export const yearOf = (ym) => String(ym).slice(0, 4)

/** Group rows by a key, preserving insertion-free sorted order of the keys. */
function groupBy(rows, keyOf) {
  const m = new Map()
  for (const r of rows) {
    const k = keyOf(r)
    if (!m.has(k)) m.set(k, [])
    m.get(k).push(r)
  }
  return m
}

const mean = (xs) => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : 0)

// 'Compliant' is not a defect — it records that a criterion was checked and nothing was
// wrong. 'Inventory Record Accuracy' as a CLASSIFICATION duplicates what the whole
// Record Accuracy page measures far better. Both are excluded from the findings
// visuals, matching the report's own two per-visual filters.
const NON_DEFECT = new Set(['Compliant', 'Inventory Record Accuracy'])
export const isDefect = (f) => !NON_DEFECT.has(f.classification)
export const isOpen = (f) => f.status === 'Open'

// ---------------------------------------------------------------------------
// Summary page
// ---------------------------------------------------------------------------

/**
 * The scorecard: one row per inspection criterion.
 *
 * `rating` is the score EARNED against that criterion's weight, averaged across every
 * audit in the selection — so the five rows sum to the overall rating and each row's
 * distance from its own weight is how much was lost there. The weight is read from the
 * data rather than hard-coded, because the audit form's weighting is the form's to
 * change, not this file's.
 */
export function scorecard(ratings) {
  const byCriteria = groupBy(ratings, (r) => r.criteria)
  const rows = AUDIT_CRITERIA
    .filter((c) => byCriteria.has(c))
    .map((c) => {
      const rows = byCriteria.get(c)
      return {
        num: rows[0].num,
        criteria: c,
        weight: mean(rows.map((r) => r.weight)),
        rating: mean(rows.map((r) => r.rating)),
        audits: rows.length,
      }
    })
  return {
    rows,
    weight: rows.reduce((a, r) => a + r.weight, 0),
    rating: rows.reduce((a, r) => a + r.rating, 0),
  }
}

/**
 * Final rating per month: the average of each audit's overall rating.
 *
 * An audit's overall rating is the SUM of its five criteria ratings (they are already
 * weighted), and a month's figure is the mean of the audits that fell in it — never the
 * mean of the individual ratings, which would divide by five and read 17%.
 */
export function ratingsByMonth(ratings) {
  const byAudit = groupBy(ratings, auditKey)
  const totals = new Map()
  for (const [key, rows] of byAudit) {
    const month = key.slice(0, 7)
    if (!totals.has(month)) totals.set(month, [])
    totals.get(month).push(rows.reduce((a, r) => a + r.rating, 0))
  }
  return [...totals.keys()].sort().map((ym) => ({
    key: ym,
    year: yearOf(ym),
    label: monthLabel(ym),
    rating: mean(totals.get(ym)),
    audits: totals.get(ym).length,
  }))
}

/**
 * Top 5 high-risk audit areas — the finding classifications with the most still-open
 * findings in the selection.
 *
 * THIS ONE DELIBERATELY DOES NOT MATCH THE POWER BI VISUAL, and that is a fix rather
 * than a drift. The report's own chart carries a Top-N filter on the FINDINGS TEXT
 * column ordered by `Min(Findings)` descending — which ranks prose alphabetically, not
 * by risk — so it silently keeps only the six alphabetically-last finding sentences
 * before counting. That is why the unfiltered chart reads 9, 1, 1, 1 out of 201 open
 * findings, why each slicer change re-picks a different six, and why the Vertical and
 * Horizontal splits do not add up to the total. The title's promise — which areas carry
 * the most open risk — is what is computed here instead.
 */
export function highRiskAreas(findings, limit = 5) {
  const open = findings.filter((f) => isDefect(f) && isOpen(f))
  const counts = groupBy(open, (f) => f.classification)
  return [...counts]
    .map(([name, rows]) => ({
      name,
      value: rows.length,
      projects: new Set(rows.map((r) => r.project)).size,
      criteria: rows[0].criteria,
    }))
    .sort((a, b) => b.value - a.value || a.name.localeCompare(b.name))
    .slice(0, limit)
}

/**
 * Open findings grouped by classification and root cause — the Summary's detail table.
 *
 * Root cause is the auditor's own wording and is inconsistent by nature: some rows carry
 * a bare 'People' / 'Process' / 'Tools', others a full sentence prefixed with one of
 * those. It is grouped verbatim (as the report does) rather than normalised, because
 * collapsing "People" and "People — lack of subcontractor initiative…" into one row
 * would destroy the only detail that makes the table actionable. `theme` pulls the
 * People/Process/Tools prefix out separately so the table can still be read by theme.
 */
export function rootCauseTable(findings) {
  const open = findings.filter((f) => isDefect(f) && isOpen(f))
  const rows = [...groupBy(open, (f) => `${f.classification}␀${f.rootCause}`)].map(([, rows]) => ({
    classification: rows[0].classification,
    rootCause: rows[0].rootCause,
    theme: rootCauseTheme(rows[0].rootCause),
    count: rows.length,
    projects: [...new Set(rows.map((r) => r.project))].sort(),
    status: 'Open',
  }))
  return rows.sort((a, b) =>
    b.count - a.count ||
    a.classification.localeCompare(b.classification) ||
    a.rootCause.localeCompare(b.rootCause))
}

// The audit's own People / Process / Tools taxonomy, read off the front of the root
// cause where the auditor wrote it. Returns '' when the text does not open with one —
// inventing a theme for those would misreport the split.
const THEMES = ['People', 'Process', 'Tools']
export function rootCauseTheme(text) {
  const t = String(text || '').trim()
  return THEMES.find((k) => t.toLowerCase() === k.toLowerCase() || t.toLowerCase().startsWith(`${k.toLowerCase()} -`)) || ''
}

/** Headline counters for the Summary's KPI row. */
export function summaryKpis({ ratings, findings, counts }) {
  const audits = groupBy(ratings, auditKey)
  const defects = findings.filter(isDefect)
  const open = defects.filter(isOpen)
  const closed = defects.filter((f) => f.status === 'Closed')
  const hit = counts.filter((c) => c.hitMiss === 'HIT').length
  return {
    audits: audits.size,
    projects: new Set([...audits.keys()].map((k) => k.split('|')[1])).size,
    rating: scorecard(ratings).rating,
    open: open.length,
    closed: closed.length,
    // Of the findings this selection ever raised, how many have been put to bed. The
    // denominator excludes N/A rows, which are neither open nor closed.
    closureRate: open.length + closed.length ? closed.length / (open.length + closed.length) : 0,
    countedLines: counts.length,
    accuracy: counts.length ? hit / counts.length : 0,
    exposure: counts.reduce((a, c) => a + c.varianceValue, 0),
  }
}

// ---------------------------------------------------------------------------
// Inventory Record Accuracy page
// ---------------------------------------------------------------------------

/**
 * HIT / MISS counts and the resulting accuracy, per audit month.
 *
 * Accuracy is the share of counted lines the auditor marked HIT — the sheet's own
 * verdict per line, not a recomputation from the variance, so the app can never
 * disagree with the signed count.
 */
export function accuracyByMonth(counts) {
  const byMonth = groupBy(counts, (c) => c.date.slice(0, 7))
  return [...byMonth.keys()].sort().map((ym) => {
    const rows = byMonth.get(ym)
    const hit = rows.filter((r) => r.hitMiss === 'HIT').length
    return {
      key: ym,
      year: yearOf(ym),
      label: monthLabel(ym),
      hit,
      miss: rows.length - hit,
      lines: rows.length,
      accuracy: rows.length ? hit / rows.length : 0,
    }
  })
}

/**
 * Financial impact per calendar month — the peso exposure the counts uncovered.
 *
 * Grouped by MONTH ACROSS YEARS, exactly as the report does: February is one bar
 * carrying both February 2025 and February 2026. That is a seasonal read rather than a
 * timeline, so the row carries `years` and the tooltip says which years it merges —
 * without that the bar is easy to misread as a single month's number.
 */
export function varianceByMonth(counts) {
  const byMonth = groupBy(counts, (c) => c.date.slice(5, 7))
  return [...byMonth.keys()].sort().map((mm) => {
    const rows = byMonth.get(mm)
    return {
      key: mm,
      label: MONTHS[Number(mm) - 1] || mm,
      value: rows.reduce((a, r) => a + r.varianceValue, 0),
      lines: rows.length,
      years: [...new Set(rows.map((r) => yearOf(r.date)))].sort(),
    }
  })
}

/**
 * The variance table: one row per item description, summed across every count in the
 * selection, ordered by the worst shortfall first.
 *
 * Quantities are summed across different UOMs where an item was counted in more than
 * one — the report does the same, and the alternative (one row per description+UOM)
 * splits the same material into rows that look like duplicates. `uoms` records when
 * that has happened so the cell can say so instead of implying a single unit.
 */
export function itemVariance(counts) {
  const byItem = groupBy(counts, (c) => c.description || c.itemCode)
  return [...byItem].map(([name, rows]) => ({
    name,
    itemCode: rows[0].itemCode,
    uoms: uomList(rows),
    systemQty: rows.reduce((a, r) => a + r.systemQty, 0),
    actualQty: rows.reduce((a, r) => a + r.actualQty, 0),
    variance: rows.reduce((a, r) => a + r.variance, 0),
    varianceValue: rows.reduce((a, r) => a + r.varianceValue, 0),
    lines: rows.length,
    misses: rows.filter((r) => r.hitMiss === 'MISS').length,
  })).sort((a, b) => a.variance - b.variance || b.varianceValue - a.varianceValue)
}

// The count sheet spells one unit as many as five ways — pc, PC, pcs, PCS, PC/S — so a
// cell listing every spelling an item was counted in reads as five different units. They
// are folded case- and punctuation-insensitively, keeping the first spelling of each as
// written. What survives is a real disagreement (meter vs lm vs box), which is worth
// showing: it is why summing that item's quantity across counts is approximate.
function uomList(rows) {
  const seen = new Map()
  for (const r of rows) {
    if (!r.uom) continue
    const k = r.uom.toLowerCase().replace(/[^a-z]/g, '')
    if (!seen.has(k)) seen.set(k, r.uom)
  }
  return [...seen.values()]
}

// ---------------------------------------------------------------------------
// Audit Findings page
// ---------------------------------------------------------------------------

/**
 * Findings raised and closed per month, with the running total of open ones.
 *
 * `closed` is returned NEGATIVE so the two series read as one signed column per month —
 * raised above the zero rule, resolved below it. The cumulative line is the running sum
 * of OPEN findings only and never comes back down: a closed finding was closed against
 * an action plan, not un-raised, so subtracting it would make the line say "risk went
 * away" when what happened is "risk was dealt with". This matches the report's own
 * measure, and the line's last point is therefore the selection's total open count.
 */
export function findingsByMonth(findings) {
  const byMonth = groupBy(findings, (f) => f.date.slice(0, 7))
  let cumulative = 0
  return [...byMonth.keys()].sort().map((ym) => {
    const rows = byMonth.get(ym)
    const open = rows.filter(isOpen).length
    cumulative += open
    return {
      key: ym,
      year: yearOf(ym),
      label: monthLabel(ym),
      open,
      closed: -rows.filter((f) => f.status === 'Closed').length,
      cumulative,
      audits: new Set(rows.map(auditKey)).size,
    }
  })
}

// Days-since-audit bands for open findings. The report draws these but filters the
// 31-60 band out of its own chart, so its bars add up to less than its own open count
// (58 of 69 on Security and Safety). All five are kept here.
export const AGING_BANDS = [
  { key: '0-30', label: '0–30 days', max: 30 },
  { key: '31-60', label: '31–60 days', max: 60 },
  { key: '61-90', label: '61–90 days', max: 90 },
  { key: '91-120', label: '91–120 days', max: 120 },
  { key: '120+', label: 'Over 120 days', max: Infinity },
]

/**
 * How long the still-open findings have been open.
 *
 * Aged from the DATE OF AUDIT — the day the defect was raised — against today's real
 * date, floored at the latest audit on file so a workbook that runs ahead of the clock
 * can never produce a negative age. Aging is a live fact, so this figure moves on its
 * own between imports; that is deliberate, and the card says as of when.
 */
export function agingBands(findings, asOf = auditAsOf()) {
  const open = findings.filter((f) => isDefect(f) && isOpen(f))
  const anchor = Date.parse(asOf)
  const bands = AGING_BANDS.map((b) => ({ ...b, count: 0, rows: [] }))
  for (const f of open) {
    const age = Math.max(0, Math.round((anchor - Date.parse(f.date)) / 86400000))
    const band = bands.find((b) => age <= b.max) || bands[bands.length - 1]
    band.count += 1
    band.rows.push(f)
  }
  return bands
}

/** The aging anchor: today, or the latest audit on file if that is later. */
export function auditAsOf() {
  const today = new Date()
  const iso = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${String(today.getDate()).padStart(2, '0')}`
  const latest = AUDIT_FINDINGS.reduce((m, f) => (f.date > m ? f.date : m), '')
  return latest > iso ? latest : iso
}

/** Days a finding has been open, or null once it is closed. */
export function findingAge(f, asOf = auditAsOf()) {
  if (!isOpen(f) || !f.date) return null
  return Math.max(0, Math.round((Date.parse(asOf) - Date.parse(f.date)) / 86400000))
}
